#include <vector>
#include <algorithm>

class Solution {
public:
    int maxDotProduct(std::vector<int>& nums1, std::vector<int>& nums2) {
        int n = nums1.size(), m = nums2.size();
        std::vector<std::vector<int>> dp(n + 1, std::vector<int>(m + 1, -1e9));
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= m; ++j) {
                int prod = nums1[i - 1] * nums2[j - 1];
                dp[i][j] = std::max({
                    prod,
                    prod + std::max(0, dp[i - 1][j - 1]),
                    dp[i - 1][j],
                    dp[i][j - 1]
                });
            }
        }
        return dp[n][m];
    }
};

class Solution {
    public int maxDotProduct(int[] nums1, int[] nums2) {
        int n = nums1.length, m = nums2.length;
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) dp[i][j] = -1000000000;
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int prod = nums1[i - 1] * nums2[j - 1];
                dp[i][j] = Math.max(prod, Math.max(prod + Math.max(0, dp[i - 1][j - 1]), Math.max(dp[i - 1][j], dp[i][j - 1])));
            }
        }
        return dp[n][m];
    }
}

var maxDotProduct = function(nums1, nums2) {
    const n = nums1.length, m = nums2.length;
    const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(-Infinity));
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            const prod = nums1[i - 1] * nums2[j - 1];
            dp[i][j] = Math.max(
                prod,
                prod + Math.max(0, dp[i - 1][j - 1]),
                dp[i - 1][j],
                dp[i][j - 1]
            );
        }
    }
    return dp[n][m];
};
